/*
 * A094615  Triangular array T of numbers generated by these rules: 1 is in T;
 *          and if x is in T, then 2x+1 and 3x+2 are in T.
 * https://oeis.org/A094615
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabl
 * Formula:   a(n) = -1 + 2^(r+1-c) * 3^c where r = floor((sqrt(8*n+1)-1)/2)
 *            (row index) c = n - r*(r+1)/2 (column index)
 * Range:     u8 n <= 18, u16 n <= 63, u32 n <= 228, u64 n <= 859,
 *            u128 n <= 3399, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <math.h>

static seq_t pow_seq_t(seq_t base, idx_t exp)
{
    seq_t result = (seq_t)1;
    while (exp) {
        result *= base;
        --exp;
    }
    return result;
}

seq_t a(idx_t n)
{
    /* Determine row r such that r*(r+1)/2 <= n < (r+1)*(r+2)/2 */
    double fn = (double) n;
    idx_t r = (idx_t)((sqrt(8.0 * fn + 1.0) - 1.0) / 2.0);

    /* First index of this row */
    idx_t start = r * (r + 1) / 2;

    /* Column within the row */
    idx_t c = n - start;

    /* Exponents for powers of 2 and 3 */
    idx_t exp2 = r + 1 - c;   /* 2^(r+1-c)  */
    idx_t exp3 = c;           /* 3^c        */

    seq_t two_pow  = pow_seq_t((seq_t)2, exp2);
    seq_t three_pow = pow_seq_t((seq_t)3, exp3);

    return two_pow * three_pow - 1;
}
